// Builds dist/SleeperAutopilot.gs: Code.gs with Index.html embedded, so setup
// is a single paste into a new Apps Script project.
//   node dev/bundle.js          write the file
//   node dev/bundle.js --check  exit 1 if the committed file is stale
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..');
const read = (f) => fs.readFileSync(path.join(dir, f), 'utf8');
const out = path.join(dir, 'dist', 'SleeperAutopilot.gs');

function build() {
  return '// GENERATED by dev/bundle.js from Code.gs + Index.html. Paste this whole file into\n' +
    '// a new Apps Script project (https://script.new). Source: fantasy/apps-script/ in the repo.\n\n' +
    read('Code.gs') + '\nvar UI_HTML = ' + JSON.stringify(read('Index.html')) + ';\n';
}

if (process.argv.includes('--check')) {
  const stale = !fs.existsSync(out) || fs.readFileSync(out, 'utf8') !== build();
  if (stale) { console.error('dist/SleeperAutopilot.gs is stale: run node dev/bundle.js'); process.exit(1); }
} else {
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, build());
  console.log('wrote', path.relative(process.cwd(), out));
}
